DROP FUNCTION IF EXISTS public.nmis_list_provider_directory(text,text,text,text,text,text,text,text,text,text,text,integer,integer,text); DROP FUNCTION IF EXISTS public.nmis_count_provider_directory(text,text,text,text,text,text,text,text,text,text); DROP FUNCTION IF EXISTS public.nmis_provider_directory_summary(text,text,text,text,text,text,text,text,text,text); CREATE OR REPLACE FUNCTION public.nmis_list_provider_directory(p_search text DEFAULT NULL::text, p_state text DEFAULT NULL::text, p_lga text DEFAULT NULL::text, p_category text DEFAULT NULL::text, p_ownership text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_contract_status text DEFAULT NULL::text, p_credential_status text DEFAULT NULL::text, p_inspection_status text DEFAULT NULL::text, p_capitation_status text DEFAULT NULL::text, p_service text DEFAULT NULL::text, p_offset integer DEFAULT 0, p_page_size integer DEFAULT 50, p_sort text DEFAULT 'provider_name'::text) RETURNS TABLE(id uuid, provider_code text, provider_name text, category text, subcategory text, ownership text, state text, lga text, contact_person text, phone text, email text, status text, contract_status text, credential_status text, inspection_status text, capitation_status text, inspection_rating text, last_inspection_date text, services text[], senatorial_district text) LANGUAGE plpgsql AS $$ BEGIN IF NOT COALESCE(public.nmis_has_any_role(ARRAY['super-admin', 'executive', 'head-of-network', 'network-officer', 'inspector', 'finance', 'claims', 'customer-service', 'provider']), false) THEN RAISE EXCEPTION 'ACCESS_RESTRICTED'; END IF; RETURN QUERY WITH provider_services_agg AS ( SELECT provider_id, array_agg(service_name) as services FROM public.provider_services GROUP BY provider_id ) SELECT p.id, p.provider_code, p.provider_name, p.category, p.subcategory, p.ownership, p.state, p.lga, p.contact_person, p.phone, p.email, p.status, p.contract_status, p.credential_status, p.inspection_status, p.capitation_status, p.inspection_rating, p.last_inspection_date::text, COALESCE(ps.services, ARRAY[]::TEXT[]), p.senatorial_district FROM public.providers AS p LEFT JOIN provider_services_agg ps ON p.id = ps.provider_id WHERE (p_search IS NULL OR lower(concat_ws(' ', p.provider_code, p.provider_name, p.category, p.subcategory, p.ownership, p.state, p.lga, p.senatorial_district)) LIKE '%' || lower(trim(p_search)) || '%') AND (p_state IS NULL OR lower(trim(p.state)) = lower(trim(p_state))) AND (p_lga IS NULL OR lower(trim(p.lga)) = lower(trim(p_lga))) AND (p_category IS NULL OR lower(trim(p.category)) = lower(trim(p_category))) AND (p_ownership IS NULL OR lower(trim(p.ownership)) = lower(trim(p_ownership))) AND (p_status IS NULL OR lower(trim(p.status)) = lower(trim(p_status))) AND (p_contract_status IS NULL OR lower(trim(p.contract_status)) = lower(trim(p_contract_status))) AND (p_credential_status IS NULL OR lower(trim(p.credential_status)) = lower(trim(p_credential_status))) AND (p_inspection_status IS NULL OR lower(trim(p.inspection_status)) = lower(trim(p_inspection_status))) AND (p_capitation_status IS NULL OR lower(trim(p.capitation_status)) = lower(trim(p_capitation_status))) AND (p_service IS NULL OR p_service = ANY(COALESCE(ps.services, ARRAY[]::TEXT[]))) ORDER BY CASE WHEN p_sort = 'provider_name' THEN lower(p.provider_name) END, CASE WHEN p_sort = 'provider_code' THEN lower(p.provider_code) END, CASE WHEN p_sort = 'state' THEN lower(p.state) END, CASE WHEN p_sort = 'lga' THEN lower(p.lga) END, CASE WHEN p_sort = 'category' THEN lower(p.category) END, CASE WHEN p_sort = 'status' THEN lower(p.status) END, p.id LIMIT p_page_size OFFSET p_offset; END; $$ ; CREATE OR REPLACE FUNCTION public.nmis_count_provider_directory(p_search text DEFAULT NULL::text, p_state text DEFAULT NULL::text, p_lga text DEFAULT NULL::text, p_category text DEFAULT NULL::text, p_ownership text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_contract_status text DEFAULT NULL::text, p_credential_status text DEFAULT NULL::text, p_inspection_status text DEFAULT NULL::text, p_capitation_status text DEFAULT NULL::text) RETURNS bigint LANGUAGE plpgsql AS $$ BEGIN IF NOT COALESCE(public.nmis_has_any_role(ARRAY['super-admin', 'executive', 'head-of-network', 'network-officer', 'inspector', 'finance', 'claims', 'customer-service', 'provider']), false) THEN RAISE EXCEPTION 'ACCESS_RESTRICTED'; END IF; RETURN ( SELECT count(*) FROM public.providers p WHERE (p_search IS NULL OR lower(concat_ws(' ', p.provider_code, p.provider_name, p.category, p.subcategory, p.ownership, p.state, p.lga, p.senatorial_district)) LIKE '%' || lower(trim(p_search)) || '%') AND (p_state IS NULL OR lower(trim(p.state)) = lower(trim(p_state))) AND (p_lga IS NULL OR lower(trim(p.lga)) = lower(trim(p_lga))) AND (p_category IS NULL OR lower(trim(p.category)) = lower(trim(p_category))) AND (p_ownership IS NULL OR lower(trim(p.ownership)) = lower(trim(p_ownership))) AND (p_status IS NULL OR lower(trim(p.status)) = lower(trim(p_status))) AND (p_contract_status IS NULL OR lower(trim(p.contract_status)) = lower(trim(p_contract_status))) AND (p_credential_status IS NULL OR lower(trim(p.credential_status)) = lower(trim(p_credential_status))) AND (p_inspection_status IS NULL OR lower(trim(p.inspection_status)) = lower(trim(p_inspection_status))) AND (p_capitation_status IS NULL OR lower(trim(p.capitation_status)) = lower(trim(p_capitation_status))) ); END; $$ ; CREATE OR REPLACE FUNCTION public.nmis_provider_directory_summary(p_search text DEFAULT NULL::text, p_state text DEFAULT NULL::text, p_lga text DEFAULT NULL::text, p_category text DEFAULT NULL::text, p_ownership text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_contract_status text DEFAULT NULL::text, p_credential_status text DEFAULT NULL::text, p_inspection_status text DEFAULT NULL::text, p_capitation_status text DEFAULT NULL::text) RETURNS TABLE(total_providers bigint, active_providers bigint, pending_providers bigint, risk_providers bigint) LANGUAGE plpgsql AS $$ BEGIN IF NOT COALESCE(public.nmis_has_any_role(ARRAY['super-admin', 'executive', 'head-of-network', 'network-officer', 'inspector', 'finance', 'claims', 'customer-service', 'provider']), false) THEN RAISE EXCEPTION 'ACCESS_RESTRICTED'; END IF; RETURN QUERY SELECT count(*) AS total_providers, count(*) FILTER (WHERE lower(trim(p.status)) = 'active') AS active_providers, count(*) FILTER (WHERE lower(trim(p.status)) = 'pending') AS pending_providers, count(*) FILTER (WHERE lower(trim(p.status)) IN ('suspended', 'blacklisted', 'expired')) AS risk_providers FROM public.providers p WHERE (p_search IS NULL OR lower(concat_ws(' ', p.provider_code, p.provider_name, p.category, p.subcategory, p.ownership, p.state, p.lga, p.senatorial_district)) LIKE '%' || lower(trim(p_search)) || '%') AND (p_state IS NULL OR lower(trim(p.state)) = lower(trim(p_state))) AND (p_lga IS NULL OR lower(trim(p.lga)) = lower(trim(p_lga))) AND (p_category IS NULL OR lower(trim(p.category)) = lower(trim(p_category))) AND (p_ownership IS NULL OR lower(trim(p.ownership)) = lower(trim(p_ownership))) AND (p_status IS NULL OR lower(trim(p.status)) = lower(trim(p_status))) AND (p_contract_status IS NULL OR lower(trim(p.contract_status)) = lower(trim(p_contract_status))) AND (p_credential_status IS NULL OR lower(trim(p.credential_status)) = lower(trim(p_credential_status))) AND (p_inspection_status IS NULL OR lower(trim(p.inspection_status)) = lower(trim(p_inspection_status))) AND (p_capitation_status IS NULL OR lower(trim(p.capitation_status)) = lower(trim(p_capitation_status))); END; $$ ;